  generationProgress.completed = 0;
  generationProgress.abc = 0;
  generationProgress.efg = 0;
  generationProgress.jkl = 0;
  generationProgress.xyz = 0;

  res.json({ 
    success: true,
    message: 'Generation started', 
    total: 1500000 
  });

  // Run generation in background
